import { analyzeGrammar } from './analysis'
import { appendDecls } from './definition'
import type { ProjectData } from './project'

// Textbook expression grammar without left recursion (moved here from DefinitionTab).
const EXAMPLE = {
  rules: `# Učebnicový príklad (výraz bez ľavej rekurzie)
E  -> T E'
E' -> + T E' | ε
T  -> F T'
T' -> * F T' | ε
F  -> ( E ) | i
`,
  def: { nonterminals: "E   výraz\nE'  zvyšok súčtu\nT   člen\nT'  zvyšok súčinu\nF   faktor\n", terminals: '+\n*\n(\n)\ni   identifikátor\n', start: 'E' },
  input: 'i + i * i',
}

/** Does the project already hold a grammar (P, N, T or S) that loading an example would overwrite? */
export function hasGrammar(data: ProjectData) {
  return Boolean(data.ll.grammar.trim() || data.def.nonterminals.trim() || data.def.terminals.trim() || data.def.start)
}

/** Replaces N, T, P, S and the simulation input with the textbook example. */
export function loadTextbookExample(data: ProjectData): ProjectData {
  return { ...data, def: { ...data.def, ...EXAMPLE.def }, ll: { ...data.ll, grammar: EXAMPLE.rules, input: EXAMPLE.input } }
}

/** Appends the symbols of P that are missing from the declared N and T ("Doplniť z pravidiel"). */
export function fillDeclarationsFromRules(data: ProjectData): ProjectData {
  const { missingN, missingT } = analyzeGrammar({ rules: data.ll.grammar, ...data.def })
  if (!missingN.length && !missingT.length) return data
  return {
    ...data,
    def: { ...data.def, nonterminals: appendDecls(data.def.nonterminals, missingN), terminals: appendDecls(data.def.terminals, missingT) },
  }
}
